"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[21476],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>d});var r=i(36672);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}},73993:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>u,contentTitle:()=>d,default:()=>o,frontMatter:()=>a,metadata:()=>r,toc:()=>h});const r=JSON.parse('{"id":"2023/04/08","title":"2023-04-08","description":"GitHub mit Ruby on Rails aufbauen","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/2023/04/08.md","sourceDirName":"2023/04","slug":"/2023/04/08","permalink":"/de/2023/04/08","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/de/docusaurus-plugin-content-docs//current/2023/04/08.md","tags":[],"version":"current","frontMatter":{"localized_date":"8. April 2023","top_news":"GitHub mit Ruby on Rails aufbauen"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-09","permalink":"/de/2023/04/09"},"next":{"title":"2023-04-07","permalink":"/de/2023/04/07"}}');var t=i(23420),s=i(3331);const a={localized_date:"8. April 2023",top_news:"GitHub mit Ruby on Rails aufbauen"},d="2023-04-08",u={},h=[{value:"GitHub mit Ruby on Rails aufbauen",id:"github-mit-ruby-on-rails-aufbauen",level:2},{value:"Fragen Sie Wirecutter: K\xf6nnen Sie mir einen nicht-intelligenten Fernseher empfehlen?",id:"fragen-sie-wirecutter-k\xf6nnen-sie-mir-einen-nicht-intelligenten-fernseher-empfehlen",level:2},{value:"Codeberg - Schnelle Open-Source-Alternative zu GitHub",id:"codeberg---schnelle-open-source-alternative-zu-github",level:2},{value:"Mehrj\xe4hriger Reis: Einmal pflanzen, immer wieder ernten",id:"mehrj\xe4hriger-reis-einmal-pflanzen-immer-wieder-ernten",level:2},{value:"Die Steuererkl\xe4rung von 60 Millionen Amerikanern ist so einfach, dass das Finanzamt sie automatisch erledigen k\xf6nnte.",id:"die-steuererkl\xe4rung-von-60-millionen-amerikanern-ist-so-einfach-dass-das-finanzamt-sie-automatisch-erledigen-k\xf6nnte",level:2},{value:"Wir m\xfcssen den Menschen sagen, dass ChatGPT sie anl\xfcgt, und nicht \xfcber Linguistik diskutieren.",id:"wir-m\xfcssen-den-menschen-sagen-dass-chatgpt-sie-anl\xfcgt-und-nicht-\xfcber-linguistik-diskutieren",level:2},{value:"Twitter erlaubt es nicht, Tweets zu retweeten, die auf Substack verlinken.",id:"twitter-erlaubt-es-nicht-tweets-zu-retweeten-die-auf-substack-verlinken",level:2},{value:"Western Digital Cloud Services f\xfcr 4 Tage ausgefallen",id:"western-digital-cloud-services-f\xfcr-4-tage-ausgefallen",level:2},{value:"Wie funktioniert das Sharding von Datenbanken?",id:"wie-funktioniert-das-sharding-von-datenbanken",level:2},{value:"Hubble sieht m\xf6gliches unkontrollierbares schwarzes Loch, das eine Spur von Sternen erzeugt",id:"hubble-sieht-m\xf6gliches-unkontrollierbares-schwarzes-loch-das-eine-spur-von-sternen-erzeugt",level:2},{value:"Die gr\xf6\xdfte Datenpanne in Neuseeland zeigt, dass die Vorratsdatenspeicherung der schlafende Riese der Datensicherheit ist",id:"die-gr\xf6\xdfte-datenpanne-in-neuseeland-zeigt-dass-die-vorratsdatenspeicherung-der-schlafende-riese-der-datensicherheit-ist",level:2},{value:"Die USA und China f\xfchren Krieg um Internetkabel",id:"die-usa-und-china-f\xfchren-krieg-um-internetkabel",level:2},{value:"Stammt das &quot;Sharding&quot; von Datenbanken aus Ultima Online?",id:"stammt-das-sharding-von-datenbanken-aus-ultima-online",level:2},{value:"Warum hat Phreesia meine medizinischen Daten weitergegeben, nachdem ich mich abgemeldet hatte?",id:"warum-hat-phreesia-meine-medizinischen-daten-weitergegeben-nachdem-ich-mich-abgemeldet-hatte",level:2},{value:"JavaScript-Algorithmen: In JavaScript implementierte Algorithmen und Datenstrukturen",id:"javascript-algorithmen-in-javascript-implementierte-algorithmen-und-datenstrukturen",level:2},{value:"SpaceX n\xe4hert sich dem ersten Starship Super Heavy Start",id:"spacex-n\xe4hert-sich-dem-ersten-starship-super-heavy-start",level:2},{value:"Discussion Service anzeigen: Musiksynthesizer mit SQL-Abfragen bauen",id:"discussion-service-anzeigen-musiksynthesizer-mit-sql-abfragen-bauen",level:2},{value:"Die l\xe4ngste gerade Linie in Gro\xdfbritannien, ohne eine \xf6ffentliche Stra\xdfe zu kreuzen",id:"die-l\xe4ngste-gerade-linie-in-gro\xdfbritannien-ohne-eine-\xf6ffentliche-stra\xdfe-zu-kreuzen",level:2},{value:"Flipper Zero wird von Amazon als &quot;Karten-Skimming-Ger\xe4t&quot; verboten.",id:"flipper-zero-wird-von-amazon-als-karten-skimming-ger\xe4t-verboten",level:2},{value:"Reverse Engineering der Facebook Messenger API",id:"reverse-engineering-der-facebook-messenger-api",level:2},{value:"Die Maschinen von Tatjana van Vark",id:"die-maschinen-von-tatjana-van-vark",level:2},{value:"Big Ball of Mud (1999)",id:"big-ball-of-mud-1999",level:2},{value:"Yann LeCun und Andrew Ng: Warum die 6-monatige KI-Pause eine schlechte Idee ist [Video]",id:"yann-lecun-und-andrew-ng-warum-die-6-monatige-ki-pause-eine-schlechte-idee-ist-video",level:2},{value:"Die NSA hat einen Online-Cybersicherheitskurs mit Hunderten von Kursen eingerichtet.",id:"die-nsa-hat-einen-online-cybersicherheitskurs-mit-hunderten-von-kursen-eingerichtet",level:2},{value:"Schlechte Systeme durch schlechte Systeme ersetzen",id:"schlechte-systeme-durch-schlechte-systeme-ersetzen",level:2},{value:"Neovim 0.9",id:"neovim-09",level:2},{value:"Fragen Sie Was ist Ihre beste Quelle, um \xfcber KI-Entwicklungen auf dem Laufenden zu bleiben?",id:"fragen-sie-was-ist-ihre-beste-quelle-um-\xfcber-ki-entwicklungen-auf-dem-laufenden-zu-bleiben",level:2},{value:"Direkte Beweise f\xfcr den Gebrauch mehrerer Drogen in der Bronzezeit durch einen menschlichen Haartest",id:"direkte-beweise-f\xfcr-den-gebrauch-mehrerer-drogen-in-der-bronzezeit-durch-einen-menschlichen-haartest",level:2},{value:"NYPD-Beamte prahlen in einer zuf\xe4lligen Aufnahme mit dem Abfeiern von \xdcberstunden",id:"nypd-beamte-prahlen-in-einer-zuf\xe4lligen-aufnahme-mit-dem-abfeiern-von-\xfcberstunden",level:2},{value:"Discussion Service anzeigen: ChatGDB - GPT-gesteuerter GDB-Assistent",id:"discussion-service-anzeigen-chatgdb---gpt-gesteuerter-gdb-assistent",level:2}];function l(e){const n={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-04-08",children:"2023-04-08"})}),"\n",(0,t.jsx)(n.h2,{id:"github-mit-ruby-on-rails-aufbauen",children:"GitHub mit Ruby on Rails aufbauen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.blog/2023-04-06-building-github-with-ruby-and-rails/",children:"Original"}),".\nGitHub.com wird mit Ruby on Rails geschrieben und von \xfcber tausend Ingenieuren mit fast 2 Millionen Codezeilen gepflegt. Das Unternehmen aktualisiert w\xf6chentlich die neuesten Rails-Commits mit Pull-Requests und Revisionspr\xfcfungen. Zu den Vorteilen dieser Upgrades geh\xf6ren eine bessere Handhabung von Datenbankverbindungen und eine schnellere Darstellung von Ansichten, verbesserte Sicherheit und ein geringeres Risiko unbekannter Probleme. Durch das Testen der neuesten Versionen werden Probleme vor der Ver\xf6ffentlichung identifiziert und behoben. Bei dem Beitrag handelt es sich um eine GitHub-Datenschutzerkl\xe4rung, die Informationen zu Produktfunktionen, Sicherheit, Geschichten, Preisen, Ressourcen, Entwickler-API, Partnern, Plattform und Support enth\xe4lt. Der Beitrag scheint keine neuen Informationen oder Ereignisse zu enthalten, und es ist unklar, warum er so viel Aufmerksamkeit erregt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35478884",children:"Discussion Service"}),".\nGitHub hat seine Plattform mit Ruby on Rails neu aufgebaut und damit das Interesse an den m\xf6glichen Auswirkungen auf das Rails-\xd6kosystem und die Anforderungen an die Testabdeckung geweckt. Die Nutzer heben die Herausforderungen hervor, die die Beherrschung von Ruby mit sich bringt, wie z. B. die extreme Testabdeckung und das Potenzial f\xfcr zuk\xfcnftige Codefehler. Einige Benutzer schlagen die Verwendung von Sorbet f\xfcr st\xe4rkere Testtypen vor. GitHubs Verwendung der Crystal-Sprache und Rubys Metaprogrammierungspotenzial wird gelobt, w\xe4hrend einige den Data-Science-Bereich von Ruby kritisieren. Microsofts k\xfcrzliches Upgrade der Rails-Plattform von Github von Version 2.3 auf 3 stellte eine Herausforderung dar, aber statische Typisierung hilft bei Upgrades. Entwickler denken \xfcber die Kompromisse zwischen technischen Trends und etablierter Stabilit\xe4t nach, wobei einige die Benutzerfreundlichkeit von Rails hervorheben, aber auch die verz\xf6gerte Ansichtsschicht. Framework-Upgrades werden am effektivsten schrittweise durchgef\xfchrt, wobei gute Tests durchgef\xfchrt werden. Viele Unternehmen halten die Aktualisierung der IT-Infrastruktur f\xfcr wichtig, die Testm\xf6glichkeiten von GitHub werden gelobt, und Sorbet wird von GitHub f\xfcr Ruby und Rails verwendet."]}),"\n",(0,t.jsx)(n.h2,{id:"fragen-sie-wirecutter-k\xf6nnen-sie-mir-einen-nicht-intelligenten-fernseher-empfehlen",children:"Fragen Sie Wirecutter: K\xf6nnen Sie mir einen nicht-intelligenten Fernseher empfehlen?"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.nytimes.com/wirecutter/blog/ask-wirecutter-dumb-tvs/",children:"Original"}),".\nWirecutter schl\xe4gt vor, intelligente Fernseher zu sichern, anstatt nicht-intelligente Optionen zu finden, um den Datenschutz zu gew\xe4hrleisten. Ungesicherten Fernsehern k\xf6nnen n\xfctzliche Funktionen fehlen. Experten raten dazu, die Datenerfassung zu deaktivieren, sich nur f\xfcr Firmware-Updates mit dem Wi-Fi zu verbinden und gelegentlich zu streamen, um sich abzumelden. Alte Fernsehger\xe4te, 4K-Monitore oder Projektoren sind Alternativen. \xc4hnliche Probleme mit dem Datenschutz bestehen auch bei anderen mit dem Internet verbundenen Ger\xe4ten."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35484594",children:"Discussion Service"}),".\nIn einem Artikel wird die Schwierigkeit er\xf6rtert, einen nicht intelligenten Fernseher ohne aufdringliche und unn\xf6tige Funktionen zu finden. Zu den vorgeschlagenen L\xf6sungen geh\xf6ren die Verwendung eines nicht angeschlossenen Smart-TVs oder das physische Trennen von Modulen, um unerw\xfcnschte Verbindungen zu verhindern. Es gibt Bedenken hinsichtlich des Datenschutzes und der Datenexfiltration. Diskussion \xfcber den Energieverbrauch, m\xf6gliche automatische Verbindungen und die langsame Inbetriebnahme von Smart-TVs durch die Nutzer. Vorschl\xe4ge f\xfcr einen m\xf6glichen Namen f\xfcr ein nicht-smartes Fernsehger\xe4t und ideale Smart-TV-Funktionen. Bedenken bez\xfcglich der Datenverfolgung und der Schwierigkeit, ein qualitativ hochwertiges, stummes Display zu starten. Nutzer diskutieren \xfcber spezifische Display-Funktionen und die Schwierigkeit, Smart-TVs unverbunden zu halten. Das unethische Verhalten von TCL und die Bedenken der Nutzer hinsichtlich des Datenschutzes werden hervorgehoben."]}),"\n",(0,t.jsx)(n.h2,{id:"codeberg---schnelle-open-source-alternative-zu-github",children:"Codeberg - Schnelle Open-Source-Alternative zu GitHub"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://codeberg.org/",children:"Original"}),".\nCodeberg.org ist eine freie und quelloffene Software-Kollaborationsplattform und Git-Hosting, die von ihren Nutzern \xfcber eine gemeinn\xfctzige Organisation in Berlin betrieben wird. Die Plattform f\xf6rdert auch eine Gemeinschaft von gleichgesinnten freien Software- und Inhaltserstellern, ohne dass Nutzerdaten verfolgt oder verkauft werden. Nutzer k\xf6nnen sich registrieren und ihre Projekte auf der Website hosten, und Codeberg e.V. unterst\xfctzt die Gemeinschaft durch Spenden und freiwillige Beitr\xe4ge. Die Website ist in mehreren Sprachen zug\xe4nglich, und die Nutzer k\xf6nnen Beitr\xe4ge zur Verbesserung der Dienste hinter Codeberg anbieten."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35480056",children:"Discussion Service"}),".\nCodeberg bietet eine schnelle, quelloffene Alternative zu Github, die sich auf die Zusammenarbeit bei freier und quelloffener Software konzentriert. Discussion Service-Benutzer diskutieren, ob Codebergs Fokus auf Open-Source-Ethik zu restriktiv ist, w\xe4hrend andere es f\xfcr sein Engagement loben. In der Diskussion \xfcber die politische Natur der IT-Infrastruktur argumentieren einige, dass Neutralit\xe4t unm\xf6glich ist, aber dennoch angestrebt werden sollte, w\xe4hrend andere behaupten, dass politische Meinungen in der IT toleranter sind als in anderen Kontexten. Discussion Service-Nutzer diskutieren auch \xfcber die Philosophie des Code-Sharings, restriktive Lizenzen und die Auswirkungen von unternehmensfreundlichen Codes auf die Erfolgsquote von FOSS. Codebergs Non-Profit-Status und sein Engagement f\xfcr freie Softwarelizenzen werden gelobt. Die schnelle Geschwindigkeit der Plattform und die unkomplizierte Benutzeroberfl\xe4che werden gesch\xe4tzt, aber es gibt Bedenken hinsichtlich des Datenschutzes. Einige empfehlen Radicle als Alternative zu zentralisierten Diensten wie Github."]}),"\n",(0,t.jsx)(n.h2,{id:"mehrj\xe4hriger-reis-einmal-pflanzen-immer-wieder-ernten",children:"Mehrj\xe4hriger Reis: Einmal pflanzen, immer wieder ernten"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.npr.org/2023/03/23/1165680024/perennial-rice-plant-once-harvest-again-and-again",children:"Original"}),".\nWissenschaftler haben mehrj\xe4hrige Reissorten gez\xfcchtet, die produktiv bleiben und nach jeder Ernte wieder nachwachsen, was enorme Vorteile f\xfcr die Umwelt, eine geringere CO2-Bilanz und ges\xfcndere B\xf6den mit sich bringt und den Landwirten das erneute S\xe4en erspart. Diese in den letzten zwei Jahrzehnten gez\xfcchteten Sorten wurden vier Jahre hintereinander von 45 000 Kleinbauern getestet und geerntet. Wenn mehr Landwirte die neuen Sorten \xfcbernehmen, k\xf6nnten die Vorteile f\xfcr die Menschen, die sie anbauen, f\xfcr die Umwelt und f\xfcr die Weltbev\xf6lkerung, die auf Reis als Grundnahrungsmittel angewiesen ist, gro\xdf sein, sagen Experten voraus."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481409",children:"Discussion Service"}),".\nMehrj\xe4hriger Reis kann die Methanemissionen von Reisfeldern verringern. Die Viehzucht hat erhebliche Auswirkungen auf die Umwelt. Der Klimawandel wird zu Nahrungsmittelknappheit und anderen Problemen f\xfchren. Methan aus Reisfeldern hat im Vergleich zu anderen Quellen keine signifikanten Auswirkungen. Mehrj\xe4hriger Reis hat potenzielle Vorteile, aber auch Herausforderungen. Experten diskutieren \xfcber Landwirtschaft und Nahrungsmittelproduktion. Der Erfolg von bew\xe4ssertem mehrj\xe4hrigem Reis wird erl\xe4utert. Mehrj\xe4hrige Pflanzen k\xf6nnen Arbeits- und Betriebsmittelkosten einsparen. Mehrj\xe4hrige Pflanzen haben Vorteile f\xfcr den Boden und die N\xe4hrstoffgewinnung."]}),"\n",(0,t.jsx)(n.h2,{id:"die-steuererkl\xe4rung-von-60-millionen-amerikanern-ist-so-einfach-dass-das-finanzamt-sie-automatisch-erledigen-k\xf6nnte",children:"Die Steuererkl\xe4rung von 60 Millionen Amerikanern ist so einfach, dass das Finanzamt sie automatisch erledigen k\xf6nnte."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.vox.com/23055489/irs-automatic-filing-prepopulated-returns",children:"Original"}),'.\nMindestens 41 % der amerikanischen Haushalte, d. h. 62 Millionen Steuererkl\xe4rungseinheiten, k\xf6nnten ihre gesamte Steuererkl\xe4rung ohne weiteres Zutun vom IRS durch "vorausgef\xfcllte Erkl\xe4rungen" erledigen lassen. Der weniger konservative Ansatz geht von 73 Millionen Steuererkl\xe4rungen bzw. 48 % aus. Das Potenzial f\xfcr automatische Erkl\xe4rungen k\xf6nnte jedes Jahr Zeit und \xc4rger sparen und die Steuersaison effizienter machen. Der Artikel geht auch kurz auf andere Themen ein, die nichts mit Steuern zu tun haben, wie z. B. den sexuellen Missbrauch von Kindern durch die katholische Kirche und die Kameras von Tesla, die auf dem Pr\xfcfstand stehen. Er hebt jedoch haupts\xe4chlich einzigartige L\xf6sungen f\xfcr wichtige Probleme hervor, die im Future Perfect Newsletter behandelt werden. Der Artikel bleibt neutral und informativ, ohne jegliche politische oder religi\xf6se Voreingenommenheit.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35476709",children:"Discussion Service"}),".\nDie Steuern von 60 Millionen Amerikanern sind f\xfcr die IRS einfach genug, um sie automatisch zu berechnen. Der einfachste Weg f\xfcr die IRS, Geld zu verdienen, ist die Pr\xfcfung von finanziell schwachen Personen. Intuit tr\xe4gt zum Ph\xe4nomen der undurchsichtigen Gesetze bei. Die Durchsetzung durch die IRS ist begrenzt, so dass Amerikaner mit geringem Einkommen h\xe4ufiger gepr\xfcft werden. Die j\xfcngsten Steuer\xe4nderungen bedeuten weniger Spielraum f\xfcr Einzelabz\xfcge. Der IRS kann seine automatischen Steuerm\xf6glichkeiten nicht aussch\xf6pfen. Der IRS-Haushalt wurde gek\xfcrzt und k\xfcrzlich aufgestockt; einige glauben, dass die zus\xe4tzlichen Mittel es dem IRS erm\xf6glichen werden, die Einnahmen zu maximieren, anstatt bestimmte Personen ins Visier zu nehmen. Vorschlag, die Steuer auf der Grundlage des Steuersatzes X zu erheben und bei Nicht\xfcbereinstimmung einen Antrag zu stellen. Vorausgef\xfcllte Steuererkl\xe4rungen w\xfcrden Zeit und Geld sparen, sind aber nicht narrensicher. Die Lobbyarbeit der Unternehmen tr\xe4gt zur Komplexit\xe4t des derzeitigen Selbstbedienungs-Steuersystems bei. Die Abzugsf\xe4higkeit der Umsatzsteuer bei Bargesch\xe4ften ist nicht automatisierbar. Die Steuererstellung vergeudet Milliarden von Dollar und Zeit."]}),"\n",(0,t.jsx)(n.h2,{id:"wir-m\xfcssen-den-menschen-sagen-dass-chatgpt-sie-anl\xfcgt-und-nicht-\xfcber-linguistik-diskutieren",children:"Wir m\xfcssen den Menschen sagen, dass ChatGPT sie anl\xfcgt, und nicht \xfcber Linguistik diskutieren."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://simonwillison.net/2023/Apr/7/chatgpt-lies/",children:"Original"}),".\nDer Artikel er\xf6rtert die Probleme im Zusammenhang mit gro\xdfen Sprachmodellen (LLMs) wie ChatGPT, die die Menschen bel\xfcgen k\xf6nnen und Fehler aufweisen, die sich nicht beheben lassen. Der Autor argumentiert, dass es wichtiger ist, die Menschen vor den Risiken der Verwendung von LLMs zu warnen, als \xfcber Linguistik zu diskutieren. Obwohl LLMs n\xfctzlich sein k\xf6nnen, sind sie nicht empfindungsf\xe4hig und man kann ihnen nicht vertrauen, dass sie sachliche Informationen liefern. Der Artikel wirft ethische Fragen dar\xfcber auf, ob wir die Menschen dazu ermutigen sollten, LLMs trotz ihrer M\xe4ngel zu benutzen oder nicht. Der Autor kommt zu dem Schluss, dass es wichtig ist, LLMs mit Vorsicht zu begegnen und betont die Notwendigkeit, die Menschen zu warnen, dass ChatGPT l\xfcgen kann."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35483823",children:"Discussion Service"}),".\nChatGPT kann Benutzer in die Irre f\xfchren und es muss wiederholt darauf hingewiesen werden, dass man ihm nicht vertrauen sollte. Seine N\xfctzlichkeit kann begrenzt sein, wenn die Neigung zu Halluzinationen nicht gel\xf6st wird. ChatGPT verf\xfcgt nicht \xfcber logische F\xe4higkeiten und kann falsche Informationen erzeugen. Einige sind von den potenziellen Fortschritten begeistert, andere kritisieren die fehlende F\xe4higkeit zur Abstraktion oder zum logischen Denken. KI-generierte Texte sind mit Skepsis zu betrachten und sollten als Assistenten betrachtet werden, die zwar belesen sind, aber m\xf6glicherweise zu Konfabulationen neigen. ChatGPT ist jedoch n\xfctzlich bei der Erstellung von Codebeispielen und der Beantwortung komplexer Fragen. Es bietet in bis zu 99 % der F\xe4lle korrekte Antworten. Die Benutzer m\xfcssen seine Grenzen kennen, um ChatGPT nicht mehr Moral als n\xf6tig zu unterstellen."]}),"\n",(0,t.jsx)(n.h2,{id:"twitter-erlaubt-es-nicht-tweets-zu-retweeten-die-auf-substack-verlinken",children:"Twitter erlaubt es nicht, Tweets zu retweeten, die auf Substack verlinken."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://arstechnica.com/tech-policy/2023/04/the-dumb-reason-twitter-wont-allow-retweeting-tweets-linking-to-substack/",children:"Original"}),".\nTwitter hat damit begonnen, Tweets mit Links zu Substack.com einzuschr\xe4nken, als Reaktion auf die Ank\xfcndigung von Substack, ein neues Produkt, Notes, zu entwickeln, das direkt mit Twitter konkurrieren wird. Nutzer haben bemerkt, dass sie Tweets mit Substack-Links nicht mehr retweeten oder beantworten k\xf6nnen, und Twitter hat anscheinend damit begonnen, das Einbetten von Tweets in Substack-Posts zu blockieren. Es wird angenommen, dass Twitter mit dieser Einschr\xe4nkung versucht, die Reichweite eines Konkurrenten auf seiner Plattform einzuschr\xe4nken. Twitter hat bereits im Dezember 2022 damit begonnen, Links zu konkurrierenden Social-Media-Plattformen zu blockieren. Substack hat noch nicht auf Fragen zu dieser Angelegenheit geantwortet."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35482222",children:"Discussion Service"}),".\nTwitter hat das Retweeten von Tweets, die auf Substack verlinken, verboten, da das Liken solcher Beitr\xe4ge die Diskussion unterdr\xfcckt. Der Schritt hat Kritik an der freien Meinungs\xe4u\xdferung, Elon Musks Haltung dazu und der Konkurrenz von Substack ausgel\xf6st. Mastodon wird von einigen als Ersatz f\xfcr Twitter angesehen. Es werden Diskussionen \xfcber PR, die Sucht nach sozialen Medien und fragw\xfcrdige Praktiken gef\xfchrt. Keine neue Technologie oder Ver\xf6ffentlichung wird erw\xe4hnt."]}),"\n",(0,t.jsx)(n.h2,{id:"western-digital-cloud-services-f\xfcr-4-tage-ausgefallen",children:"Western Digital Cloud Services f\xfcr 4 Tage ausgefallen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://status.mycloud.com/os4",children:"Original"}),".\nWestern Digital erlebte einen Ausfall, der am 2. April begann und sich auf Dienste wie My Cloud, My Cloud Home, SanDisk ibi und andere verwandte Produkte auswirkte, wobei am 3. April ein Update ver\xf6ffentlicht wurde. Die St\xf6rung dauerte bis zum 7. April an und beeintr\xe4chtigte den Zugriff auf Dateien und Anwendungen. Ein lokaler Zugriff ist m\xf6glich, so dass die Nutzer von einem Windows- oder MacOS-Computer aus auf ihre pers\xf6nlichen Dateien zugreifen k\xf6nnen. Zu den weiteren Vorf\xe4llen in der Vergangenheit geh\xf6rten zeitweilige Zugriffsprobleme, zeitweilige Passwortr\xfccksetzungen und zeitweilige Verbindungsprobleme mit Cloud-Diensten. Bei einigen Nutzern in China kann es ebenfalls zu Zugriffsproblemen kommen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35478007",children:"Discussion Service"}),".\nDie Cloud-Dienste von Western Digital sind seit vier Tagen nicht mehr verf\xfcgbar. In den Kommentaren werden der Ausfall und die Garantie des Unternehmens diskutiert. Einige Nutzer diskutieren die Grenzen des Sprachmodells von GPT und seines Weltmodells, wobei Fragen zum Verst\xe4ndnis komplexer Konzepte aufgeworfen werden. In den Kommentaren werden auch Rechtsbegriffe im Zusammenhang mit der Serviceverantwortung und den Garantien der GPT er\xf6rtert. Nutzer diskutieren \xfcber den Wert von Statusseiten bei Ausf\xe4llen, wobei einige alternative Methoden wie Chat vorschlagen. Die Nutzer diskutieren die Vor- und Nachteile des Selbst-Hostings und w\xfcnschen sich eine Zukunft, in der der Zugriff auf die Medien der Nutzer von \xfcberall m\xf6glich ist. Die Probleme, die Western Digital in der Vergangenheit mit nicht ordnungsgem\xe4\xdf gekennzeichneten SMR-Laufwerken hatte, haben einige Nutzer dazu veranlasst, eine R\xfcckkehr zu lokalen L\xf6sungen zu fordern."]}),"\n",(0,t.jsx)(n.h2,{id:"wie-funktioniert-das-sharding-von-datenbanken",children:"Wie funktioniert das Sharding von Datenbanken?"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://planetscale.com/blog/how-does-database-sharding-work",children:"Original"}),'.\nDer Artikel befasst sich mit dem Sharding von Datenbanken und erl\xe4utert die Vorteile des Skalierens nach unten statt nach oben, wobei verschiedene Sharding-Schemata und -Algorithmen diskutiert werden. Er behandelt wichtige Aspekte wie die Organisation der Infrastruktur, die Erstellung einer Routing-Schicht und die Migrationsplanung, wobei die Bedeutung der Wartung hervorgehoben wird. Es wird ein kurzer \xdcberblick \xfcber Sharding-Frameworks und -Tools wie Vitess und Citus gegeben, wobei CockroachDB die \xc4ra der "serverlosen" Datenbanken einl\xe4utet. PlanetScale, ein aufstrebender Akteur auf dem Markt, bietet neben seinen technischen Ressourcen eine shard-native Datenbank an, die auf MySQL und Vitess aufbaut.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35476518",children:"Discussion Service"}),".\nDebatten \xfcber die Vorteile und Herausforderungen des Sharding von Datenbanken; Entscheidung f\xfcr ein System, das zu den Daten passt; Hotkey-Durchsatz ist ein Problem beim Auto-Sharding; Spanner/Cockroach oder Dynamo/Cassandra als Alternativen; CockroachDB bietet starke Konsistenz und 2PC zwischen Shards; Komplexit\xe4t der Verteilung erfordert kostenpflichtige Dienste; Fokus auf horizontale Skalierbarkeit, um Investitionen in eine einzelne Maschine zu vermeiden; gutes Schl\xfcsseldesign kann Hotspots verhindern; Sharding nach Kunden ist \xfcblich; f\xfcr Skalierbarkeit wird mandantenf\xe4higes Sharding empfohlen; Yugabyte, Cockroach und TiDB werden erw\xe4hnt; Hashing aller Daten zur Synchronisierung nicht skalierbar; Betr\xfcger nutzen Amazons Praxis der Tabellen-Colocation aus; MongoDB erfordert einen Supportvertrag f\xfcr Unternehmen."]}),"\n",(0,t.jsx)(n.h2,{id:"hubble-sieht-m\xf6gliches-unkontrollierbares-schwarzes-loch-das-eine-spur-von-sternen-erzeugt",children:"Hubble sieht m\xf6gliches unkontrollierbares schwarzes Loch, das eine Spur von Sternen erzeugt"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://hubblesite.org/contents/news-releases/2023/news-2023-010",children:"Original"}),".\nEs ist nicht m\xf6glich, eine Zusammenfassung zu erstellen, da es sich bei dem Text um eine Fehlermeldung handelt, die besagt, dass die Anfrage aufgrund eines Konfigurationsfehlers oder zu hohen Datenverkehrs nicht erf\xfcllt werden konnte. Wenden Sie sich an den Eigent\xfcmer der Anwendung oder der Website oder lesen Sie die CloudFront-Dokumentation, um diesen Fehler zu beheben und zu vermeiden, dass er auftritt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35476359",children:"Discussion Service"}),'.\nDas Hubble-Teleskop entdeckte ein schwarzes Loch, das eine Spur von Sternen hinterlie\xdf, was zu Spekulationen \xfcber seine Auswirkungen auf das Leben und neue Orte f\xfcr die Suche nach bewohnbaren Planeten f\xfchrte. Hubble entdeckte auch eine seltene Galaxie vom Typ Hoag, die etwa doppelt so gro\xdf ist wie die Milchstra\xdfe. Wissenschaftler entdeckten ein schwarzes Loch, das Sterne aus Gas erzeugt, was das Universum beeinflussen und fortgeschrittene Zivilisationen anziehen k\xf6nnte. Ein Objekt, das sich sehr schnell durch den Weltraum bewegt, wirkt mit \xdcberschall auf das Gas ein, aber die Verwendung von "\xdcberschall" ist wahrscheinlich metaphorisch gemeint. Discussion Service-Benutzer diskutieren \xfcber Science-Fiction-Geschichten wie Das Drei-K\xf6rper-Problem, wobei sie unterschiedliche Meinungen und Empfehlungen f\xfcr andere B\xfccher des Genres \xe4u\xdfern. Die Benutzer diskutieren auch \xfcber die Seltenheit von erd\xe4hnlichem Leben und das anthropomorphe Prinzip.']}),"\n",(0,t.jsx)(n.h2,{id:"die-gr\xf6\xdfte-datenpanne-in-neuseeland-zeigt-dass-die-vorratsdatenspeicherung-der-schlafende-riese-der-datensicherheit-ist",children:"Die gr\xf6\xdfte Datenpanne in Neuseeland zeigt, dass die Vorratsdatenspeicherung der schlafende Riese der Datensicherheit ist"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.privacy.org.nz/publications/statements-media-releases/new-zealands-biggest-data-breach-shows-retention-is-the-sleeping-giant-of-data-security/",children:"Original"}),".\nMehr als eine Million neuseel\xe4ndische F\xfchrerscheine und P\xe4sse wurden durch die Datenpanne bei Latitude Financial offengelegt; einige Datens\xe4tze waren bis zu 18 Jahre alt. Der stellvertretende neuseel\xe4ndische Datenschutzbeauftragte nennt die Vorratsdatenspeicherung als kritischen Punkt bei Angriffen auf die Cybersicherheit und erkl\xe4rt, dass Unternehmen und Organisationen die Sammlung und Speicherung von Daten, die sie nicht ben\xf6tigen, einschr\xe4nken m\xfcssen. Beh\xf6rden sollten einen Zeitplan f\xfcr die Aufbewahrung personenbezogener Daten aufstellen, und Einzelpersonen sollten bei Organisationen, denen sie Daten zur Verf\xfcgung stellen, nachfragen, warum und wie diese gespeichert werden. Der Schutz der Privatsph\xe4re muss zu einem wichtigen Thema f\xfcr Unternehmen werden, das \xe4hnlich wie Gesundheit und Sicherheit gesch\xfctzt werden muss. Latitude Financial setzt sich mit allen betroffenen Kunden in Verbindung, um sie \xfcber den Datenschutzversto\xdf zu informieren und sie bei der L\xf6sung des Problems zu unterst\xfctzen, und arbeitet gleichzeitig mit den Aufsichtsbeh\xf6rden zusammen, um die Einzelheiten des Versto\xdfes aufzukl\xe4ren."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35478240",children:"Discussion Service"}),".\nDie gr\xf6\xdfte Datenschutzverletzung in Neuseeland unterstreicht die Notwendigkeit einer angemessenen Datenaufbewahrungspolitik; die L\xf6schung sollte Vorrang haben. Die GDPR hat Fortschritte gemacht, aber die Vorratsdatenspeicherung bleibt allgegenw\xe4rtig. Discussion Service-Nutzer diskutieren \xfcber verantwortungsvolle Datenerfassung, staatlichen Zugriff und Datensicherheit. Es wird \xfcber Methoden der Datenl\xf6schung und Gr\xfcnde f\xfcr die Aufbewahrung diskutiert. Pers\xf6nliche Daten m\xfcssen auf ein Minimum reduziert und als toxische Verm\xf6genswerte behandelt werden. Unternehmen m\xfcssen besser \xfcber den Datenschutz aufgekl\xe4rt werden."]}),"\n",(0,t.jsx)(n.h2,{id:"die-usa-und-china-f\xfchren-krieg-um-internetkabel",children:"Die USA und China f\xfchren Krieg um Internetkabel"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.reuters.com/investigates/special-report/us-china-tech-cables/",children:"Original"}),".\nDie USA und China streiten sich um Unterseekabel, die alles von E-Mails bis hin zu milit\xe4rischen Geheimnissen \xfcbertragen. Die US-Regierung hat in den letzten vier Jahren bei mindestens sechs privaten Unterseekabelgesch\xe4ften interveniert, um Chinas Hightech-Sektor zu isolieren und den Zugang der Chinesen zu US-Technologie zu beschr\xe4nken. Vor kurzem vergab das Wei\xdfe Haus den Auftrag f\xfcr das Kabel von Singapur nach Frankreich aus Sicherheitsgr\xfcnden an das US-Unternehmen SubCom und nicht an das chinesische Unternehmen HMN Tech. Die aggressiven Bem\xfchungen der US-Regierung, chinesische Spionage durch Unterseekabel zu verhindern, durchkreuzen die Pl\xe4ne der Tech-Giganten und sorgen f\xfcr Aufruhr in der Branche. China revanchiert sich, indem es ein von Meta unterst\xfctztes Kabelprojekt, das Kabel S\xfcdostasien-Japan 2, aufschiebt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481712",children:"Discussion Service"}),'.\nDie USA und China konkurrieren um Unterwasser-Internetkabel, wobei es um nationale Grenzen und Zensur geht. Verz\xf6gerungen und Umleitungen bei den Kabeln haben die Tech-Giganten Millionen gekostet. Experten empfehlen B\xfccher \xfcber internationale Infrastrukturen. Die USA sind besorgt \xfcber die chinesische Spionage und ihre F\xe4higkeit, den Internetverkehr zu erfassen und zu filtern. Chinas Beteiligung an der Bewegung der Blockfreien Staaten und der Belt and Road Initiative wirft Fragen auf. Vielen "Cybersicherheits"-Firmen fehlt es an qualifizierten Ingenieuren. Das Folterprogramm der CIA und die Rechenschaftspflicht f\xfcr Kriegsverbrechen werden diskutiert.']}),"\n",(0,t.jsx)(n.h2,{id:"stammt-das-sharding-von-datenbanken-aus-ultima-online",children:'Stammt das "Sharding" von Datenbanken aus Ultima Online?'}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.raphkoster.com/2009/01/08/database-sharding-came-from-uo/",children:"Original"}),".\nIch kann leider keine Zusammenfassung auf der Grundlage dieses Textes erstellen, da es sich um eine Fehlermeldung handelt, die nichts mit dem angegebenen Thema zu tun hat."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35479553",children:"Discussion Service"}),'.\nDiscussion Service-Benutzer diskutieren, wie das "Sharding" in Datenbanken von Ultima Online inspiriert wurde. Pers\xf6nliche Geschichten erz\xe4hlen, wie UO dazu f\xfchrte, das Programmieren zu lernen. Poster erinnern sich an die Spieleigenschaften von UO und seinen Einfluss auf die Programmierung.']}),"\n",(0,t.jsx)(n.h2,{id:"warum-hat-phreesia-meine-medizinischen-daten-weitergegeben-nachdem-ich-mich-abgemeldet-hatte",children:"Warum hat Phreesia meine medizinischen Daten weitergegeben, nachdem ich mich abgemeldet hatte?"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.statnews.com/2023/04/07/medical-data-privacy-phreesia/",children:"Original"}),".\nEin Bericht zeigt auf, dass medizinische Unternehmen Patientendaten ohne Zustimmung weitergeben. Die Patientin lehnte die Weitergabe von Daten ab, fand aber dennoch heraus, dass ihre Daten von Phreesia weitergegeben wurden. Vorschlag f\xfcr eine Regel, die es verbietet, Patienten zur Einwilligung zu dr\xe4ngen. Notwendigkeit einer Standard-Absage, um die Abwahl klar und einfach zu gestalten. Das derzeitige Verfahren ist m\xfchsam. Der Experte schl\xe4gt vor, den Bereich der Werbetechnik vom Gesundheitswesen zu trennen. Der Autor ist ein ethnographischer Soziologe und Datenforscher."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35484978",children:"Discussion Service"}),".\nPhreesia teilte medizinische Daten von Patienten, die sich dagegen entschieden hatten. Viele \xe4u\xdfern Bedenken hinsichtlich des Datenschutzes und der Rechenschaftspflicht und schlagen vor, dass Werbung mit sensiblen medizinischen Daten rechtlich nicht zul\xe4ssig sein sollte. Es muss eine ordnungsgem\xe4\xdfe Dokumentation und Berichterstattung erfolgen, damit solche Unternehmen f\xfcr Verst\xf6\xdfe gegen den Datenschutz zur Rechenschaft gezogen werden k\xf6nnen. Die Verwendung von elektronischen Check-Ins und dunklen Mustern durch Gesundheitsdienstleister wurde kritisiert. In den USA sind strenge Zustimmungsgesetze und die Durchsetzung der Datenerfassung erforderlich. Auch das Gewinnstreben von Gesundheitsdienstleistern und der Unmut \xfcber die Datenschutzbestimmungen f\xfcr Patienten werden in Frage gestellt."]}),"\n",(0,t.jsx)(n.h2,{id:"javascript-algorithmen-in-javascript-implementierte-algorithmen-und-datenstrukturen",children:"JavaScript-Algorithmen: In JavaScript implementierte Algorithmen und Datenstrukturen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/trekhleb/javascript-algorithms",children:"Original"}),".\nJavaScript-Algorithms ist eine umfassende Sammlung popul\xe4rer Algorithmen und Datenstrukturen, die in JavaScript implementiert sind, geordnet nach Thema und Paradigma. Sie eignet sich sowohl f\xfcr Lern- und Forschungszwecke als auch f\xfcr den Produktionseinsatz. Die Benutzer k\xf6nnen Beispiele f\xfcr mehrere popul\xe4re Algorithmen und Datenstrukturen finden, darunter Verschl\xfcsselungs-, Evolutions- und maschinelle Lernalgorithmen. Das Repository enth\xe4lt Erkl\xe4rungen, die Big-O-Notation und Links zu weiterf\xfchrender Lekt\xfcre. Es enth\xe4lt auch eine Spielwiese, auf der die Leser mit dem Code experimentieren k\xf6nnen. Fortgeschrittene Algorithmen wie Branch and Bound und dynamische Programmierung sind ebenfalls enthalten. Die Leser sollten beachten, dass Spenden willkommen sind und dass Node Version 16 oder h\xf6her erforderlich ist."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35479378",children:"Discussion Service"}),".\n\"Hacker News kommentiert das beliebte GitHub-Repository 'JavaScript-algorithms'. Benutzer diskutieren die Eignung der Sprache f\xfcr den Unterricht und den praktischen Einsatz, einige warnen vor unerwartetem Verhalten. Einige Discussion Service-Nutzer kritisieren die Implementierung der 'addBefore()'- und 'addAfter()'-Methoden von verkn\xfcpften Listen, w\xe4hrend andere anderer Meinung sind. Discussion Service-Nutzer empfehlen weitere Ressourcen, kritisieren die Effizienz von Datenstrukturen und heben den Wert der Ressourcen f\xfcr Lernalgorithmen hervor.\""]}),"\n",(0,t.jsx)(n.h2,{id:"spacex-n\xe4hert-sich-dem-ersten-starship-super-heavy-start",children:"SpaceX n\xe4hert sich dem ersten Starship Super Heavy Start"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://spacenews.com/spacex-closing-in-on-first-starship-super-heavy-launch/",children:"Original"}),".\nSpaceX plant den ersten Start des Starship-Raumschiffs in Originalgr\xf6\xdfe Ende April, vorbehaltlich der beh\xf6rdlichen Genehmigung; die Federal Aviation Administration hat in ihrem Operations Plan Advisory Dokument einen Starttermin f\xfcr den 17. April vorgesehen, mit Ausweichdaten vom 18. bis 21. April; Starship wurde vollst\xe4ndig auf der Startrampe in der Starbase-Anlage in Boca Chica, Texas, aufgebaut, und das Unternehmen plant eine Startprobe in der n\xe4chsten Woche, gefolgt von einem ersten integrierten Flugtest etwa eine Woche sp\xe4ter; es ist unklar, ob Starship in die Umlaufbahn eintritt und dann sofort einen Deorbit-Brand durchf\xfchrt, um abzuspringen, oder ob es sich um einen langen suborbitalen Flug handelt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481775",children:"Discussion Service"}),".\nSpaceX steht kurz vor dem Start von Starship Super Heavy, wobei in den Kommentaren die Bedeutung f\xfcr die kommerzielle und milit\xe4rische Raumfahrt und ein Umdenken betont wird. Staatliche Auftr\xe4ge machen mindestens 80 % der Einnahmen von SpaceX aus. Die kryogenen Fl\xfcssigtreibstoffraketen von Starship sind f\xfcr Abschreckungsmissionen geeignet. Die Finanzierung von Raketenstarts ist nicht nur von der NASA abh\xe4ngig. Video zum Vergleich von Raketengr\xf6\xdfen erregt Aufmerksamkeit. SpaceX peilt vorl\xe4ufig den Start am 20.4. an. FAA pr\xfcft Sicherheitsbedenken. Gemischte Reaktionen auf Musks piet\xe4tlose Haltung."]}),"\n",(0,t.jsx)(n.h2,{id:"discussion-service-anzeigen-musiksynthesizer-mit-sql-abfragen-bauen",children:"Discussion Service anzeigen: Musiksynthesizer mit SQL-Abfragen bauen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/ClickHouse/NoiSQL",children:"Original"}),".\nEin GitHub-Repository namens NoiSQL erm\xf6glicht die Erzeugung musikalischer Kl\xe4nge mit SQL-Abfragen unter Verwendung von Grundwellen, Oszillatoren, Sequenzern, LFOs und Rauschgeneratoren. Die in einem 44,1 kHz 16-Bit-Stereo-PCM-Format erstellten Signale k\xf6nnen von den Benutzern durch die Definition von Funktionen und Ausdr\xfccken in SQL gesteuert werden. NoiSQL bietet Anleitungen und Beispiele, um den Umgang mit dem Programm zu erlernen. Das Projekt kann Musiknoten und Rhythmen mit ClickHouse erzeugen und verschiedene Dateiformate erstellen. Obwohl das Projekt einige Einschr\xe4nkungen aufweist, ist es ein innovativer Weg, um mit den Funktionen von ClickHouse zu experimentieren, und es k\xf6nnte m\xf6glicherweise erweitert werden, um auch Videos zu erzeugen. Benutzer k\xf6nnen neue Beispiele zum Projekt beisteuern."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35482636",children:"Discussion Service"}),".\nEin Projekt zur Erstellung von Synthesizern mit SQL-Abfragen. Discussion Service-Kommentatoren sch\xe4tzen die einzigartige Idee und erw\xe4hnen \xe4hnliche Projekte. Einige Benutzer weisen auf den Mangel an Erkl\xe4rungen und die potenzielle Anf\xe4lligkeit f\xfcr SQL-Injektionen hin."]}),"\n",(0,t.jsx)(n.h2,{id:"die-l\xe4ngste-gerade-linie-in-gro\xdfbritannien-ohne-eine-\xf6ffentliche-stra\xdfe-zu-kreuzen",children:"Die l\xe4ngste gerade Linie in Gro\xdfbritannien, ohne eine \xf6ffentliche Stra\xdfe zu kreuzen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://www.statsmapsnpix.com/2023/04/the-longest-straight-line-in-great.html",children:"Original"}),".\nIn Gro\xdfbritannien wurde eine l\xe4ngere gerade Linie gefunden, ohne eine \xf6ffentliche Stra\xdfe zu kreuzen, als die von Ordnance Survey im Jahr 2019 ermittelte. Die l\xe4ngste gerade Linie zwischen Stra\xdfen in Gro\xdfbritannien ist auch die l\xe4ngste in ganz Gro\xdfbritannien. Das OS Open Roads-Produkt bietet eine Menge gro\xdfartiger offener Daten, aber manchmal enth\xe4lt es auch Stra\xdfen, die nicht \xf6ffentlich sind. Eingeschr\xe4nkte lokale Zugangsstra\xdfen sind in der Regel unbefestigte Privatwege. Die l\xe4ngste Strecke Gro\xdfbritanniens liegt westlich der A9 und nicht \xf6stlich. Obwohl die Kartierungsdaten n\xfctzlich sind, sollten sie mit Vorsicht genossen werden."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481380",children:"Discussion Service"}),".\nEntdeckung der l\xe4ngsten geraden Linie Gro\xdfbritanniens; m\xf6glicherweise ist sie nicht ganz gerade. Einige Diskussionen \xfcber die Entfernung von Stra\xdfen, die Zug\xe4nglichkeit von unbefestigten Stra\xdfen und die Bev\xf6lkerung. Benutzer erw\xe4hnen abgelegene Gebiete auf der ganzen Welt und die M\xf6glichkeit, die Suche zu automatisieren. Eine Diskussion \xfcber das Schengener Abkommen und Passstatistiken."]}),"\n",(0,t.jsx)(n.h2,{id:"flipper-zero-wird-von-amazon-als-karten-skimming-ger\xe4t-verboten",children:'Flipper Zero wird von Amazon als "Karten-Skimming-Ger\xe4t" verboten.'}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.bleepingcomputer.com/news/technology/flipper-zero-banned-by-amazon-for-being-a-card-skimming-device-/",children:"Original"}),'.\nAmazon hat den Verkauf von Flipper Zero auf seiner Plattform verboten, da es sich um ein "Karten-Skimming-Ger\xe4t" handelt. Bei dem Ger\xe4t handelt es sich um ein kompaktes, tragbares und programmierbares Werkzeug, mit dem man mit verschiedenen digitalen und Hardware-Ger\xe4ten experimentieren und diese testen kann. Benutzer haben seine F\xe4higkeiten vorgef\xfchrt und damit Amazons Verbot ausgel\xf6st. Einige Links zu fr\xfcheren Amazon-Seiten, auf denen das Flipper Zero-Tool verkauft wurde, sind tot, w\xe4hrend andere es als "nicht verf\xfcgbar" auflisten. Die brasilianische Nationale Telekommunikationsbeh\xf6rde hat au\xdferdem eingehende Flipper Zero-K\xe4ufe beschlagnahmt, weil sie angeblich von Kriminellen verwendet wurden. Sie k\xf6nnen Flipper Zero immer noch \xfcber den offiziellen Shop des Herstellers erwerben.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481580",children:"Discussion Service"}),".\nAmazon verbietet den Kauf von Flipper Zero, da es als Karten-Skimming-Ger\xe4t angesehen wird, aber das Ger\xe4t kann im offiziellen Store gekauft werden. Die K\xe4ufer finden es interessant, aber nicht n\xfctzlich. Die Politik des Lockpick-Verbots ist inkonsistent und undokumentiert. Die Hersteller von Flipper Zero nutzen ein in den USA ans\xe4ssiges Unternehmen f\xfcr Zahlungen, was zu Sicherheitsbedenken f\xfchrt. Amazons Motivation wurde in Frage gestellt, um Schlagzeilen zu vermeiden, die sie mit Kriminalit\xe4t in Verbindung bringen. Flipper Zero wurde aufgrund seines Potenzials f\xfcr illegale Aktivit\xe4ten verboten, aber einige argumentieren, dass es mit Amazons Richtlinien nicht vereinbar ist. Einige sehen die M\xf6glichkeit, dass Amazon seine eigene Nachahmungsversion entwickelt. Flipper Zero wurde von Amazon und eBay entfernt, kann aber weiterhin \xfcber die offizielle Website erworben werden."]}),"\n",(0,t.jsx)(n.h2,{id:"reverse-engineering-der-facebook-messenger-api",children:"Reverse Engineering der Facebook Messenger API"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://intuitiveexplanations.com/tech/messenger",children:"Original"}),".\nDer Autor hat die Facebook Messenger API zur\xfcckentwickelt, um Messyger zu erstellen, ein Kommandozeilenprogramm. Der Beitrag erkl\xe4rt den Anmeldeprozess und Cookies und bietet Python-Code auf GitHub. Ethisches Verhalten wird hervorgehoben, und es werden Tipps f\xfcr Anfragen au\xdferhalb des Browsers gegeben."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35477160",children:"Discussion Service"}),".\nEntwickler beklagen aufgebl\xe4hte und ineffiziente Messenger-API. Facebook-Apps-Bibliothek hat JNI-Bindungen. Bedarf an Clients von Drittanbietern, Digital Markets Act wird zitiert. Bedenken wegen Spam und Datenerfassung, gemeinsame Reverse-Engineering-Tools. Profitmotive treiben die Spam-Reduzierung voran, einige unterst\xfctzen das Eingreifen des Staates. Regulierung sollte sich auf Cloud-Anbieter konzentrieren, nicht auf Walled Gardens. Nutzer hinterfragen den Begriff des Eigentums und Rettungsaktionen f\xfcr Unternehmen."]}),"\n",(0,t.jsx)(n.h2,{id:"die-maschinen-von-tatjana-van-vark",children:"Die Maschinen von Tatjana van Vark"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://craftsmanshipmuseum.com/artisan/tatjana-van-vark/",children:"Original"}),".\nTatjana van Vark, eine unabh\xe4ngige Forscherin aus den Niederlanden, hat eine Vielzahl von wissenschaftlichen Instrumenten gebaut, nachgebaut und restauriert. Ihre aufw\xe4ndigen Projekte zeichnen sich durch hervorragende handwerkliche F\xe4higkeiten und Liebe zum Detail aus, wobei die Komplexit\xe4t oft \xfcber den \xe4u\xdferen Anschein hinausgeht. Tatjanas Arbeit hat sie in viele Bereiche der Wissenschaft gef\xfchrt: Sie baute Ger\xe4te aus den Bereichen Elektronik, Optik, Kryptologie, organische Chemie und mehr. Trotz ihrer autodidaktischen F\xe4higkeiten als Mechanikerin verf\xfcgt ihre Werkstatt \xfcber hochwertige Maschinen, die den Anforderungen ihrer Pr\xe4zisionsarbeit gerecht werden. Ihre Arbeit ist wissenschaftliche Handwerkskunst auf h\xf6chstem Niveau, und auf ihrer Website sind beeindruckende Fotos zu sehen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35483539",children:"Discussion Service"}),".\nDie Arbeit von Tatjana van Vark ist unglaublich, und sie ist eine extreme Hackerin, die Instrumente von Grund auf neu konstruiert. Sie verf\xfcgt \xfcber ein breites Spektrum an F\xe4higkeiten und hat viele Werke geschaffen, deren Durchsicht ein ganzes Leben dauern w\xfcrde. Es besteht die Sorge, dass die Zahl der Experten schrumpft, da sich die Technologie schneller weiterentwickelt, als wir sie lehren k\xf6nnen. Tatjana van Vark und Handwerker wie sie hat es noch nie gegeben."]}),"\n",(0,t.jsx)(n.h2,{id:"big-ball-of-mud-1999",children:"Big Ball of Mud (1999)"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://www.laputan.org/mud/",children:"Original"}),".\nDer Artikel untersucht die BIG BALL OF MUD-Softwarearchitektur und warum sie trotz hochm\xfctiger Ans\xe4tze fortbesteht. Es werden sieben Muster er\xf6rtert, darunter Wegwerfcode und st\xfcckweises Wachstum, sowie die dahinter stehenden Ursachen, wie z.B. Zeitdruck und Vernachl\xe4ssigung der Architektur. Eine verfr\xfchte Architektur kann die Entwicklung behindern, und Unerfahrenheit oder Fluktuation der Mitarbeiter k\xf6nnen die Ausgereiftheit einschr\xe4nken. Paarprogrammierung und Code-Reviews werden f\xfcr eine sofortige \xdcberpr\xfcfung empfohlen, w\xe4hrend Refactoring, Reparatur und Konsolidierung entscheidend f\xfcr die Bek\xe4mpfung des BIG BALL OF MUD sind. Es wird die Bedeutung von inkrementellem Wachstum, Wartung, Anpassung und rigorosen Tests betont. Der Neuaufbau eines Systems kann notwendig sein, aber Refactoring kann eine Alternative bieten, indem es architektonische Elemente aus dem aktuellen System herausholt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481309",children:"Discussion Service"}),'.\nDer Artikel "Big Ball of Mud (1999)" ist ein viel beachtetes Werk \xfcber Software Engineering. Mehrere Benutzer loben seine Einsicht und Relevanz und zitieren ihn als eine umfassende Erkl\xe4rung f\xfcr das, was man jede Woche in der Praxis erlebt. Andere verweisen auf andere, \xe4hnlich wichtige Artikel oder sp\xe4tere Entwicklungen in der Softwaretechnik, wie z. B. Microservices. Einige Nutzer kommentieren ihre pers\xf6nlichen Erfahrungen in Bezug auf den Artikel. Schlie\xdflich kritisieren einige Nutzer die Formatierung des Artikels oder weisen darauf hin, dass er schon einmal ver\xf6ffentlicht wurde.']}),"\n",(0,t.jsx)(n.h2,{id:"yann-lecun-und-andrew-ng-warum-die-6-monatige-ki-pause-eine-schlechte-idee-ist-video",children:"Yann LeCun und Andrew Ng: Warum die 6-monatige KI-Pause eine schlechte Idee ist [Video]"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.youtube.com/watch?v=BY9KV8uCtj4",children:"Original"}),".\nDies ist nicht der eigentliche Inhalt des Artikels. Bitte stellen Sie mir den Text zur Verf\xfcgung, damit ich ihn zusammenfassen kann."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35484093",children:"Discussion Service"}),".\nYann LeCun und Andrew Ng kritisieren die 6-monatige KI-Pause, da sie unrealistisch sei und OpenAI einen Vorteil verschaffe. Es werden Debatten \xfcber den KI-Winter, die Darstellung menschlicher Gedanken und gesellschaftliche St\xf6rungen hervorgehoben. Der Fortschritt der KI bietet unerwartete F\xe4higkeiten, die \xfcber Text hinausgehen, und es werden Bedenken \xfcber Arbeitsplatzverluste und Armut ge\xe4u\xdfert. Experten sind geteilter Meinung \xfcber die Wirksamkeit der KI-Entwicklungspause und die Risiken einer unregulierten KI. Die potenzielle Bedrohung durch AGI, die die menschliche Intelligenz \xfcbertrifft, und Deep-Learning-\xdcberwachungstechnologien werden ebenso angesprochen wie Bedenken hinsichtlich der Ausrichtung von KI an menschlichen Zielen."]}),"\n",(0,t.jsx)(n.h2,{id:"die-nsa-hat-einen-online-cybersicherheitskurs-mit-hunderten-von-kursen-eingerichtet",children:"Die NSA hat einen Online-Cybersicherheitskurs mit Hunderten von Kursen eingerichtet."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://clark.center/c/nccp",children:"Original"}),".\nDie NSA hat einen Online-Cybersicherheitskurs mit Hunderten von Kursen entwickelt. Der Kurs mit der Bezeichnung CLARK deckt ein breites Spektrum an Themen ab, darunter Netzwerksicherheit, Kryptographie und Cyber-Bedrohungen. Die Kurse sind sowohl f\xfcr Anf\xe4nger als auch f\xfcr Experten gedacht und k\xf6nnen von jedem, der \xfcber eine Internetverbindung verf\xfcgt, kostenlos besucht werden. Der Kurs war nicht unumstritten, da einige Kritiker behaupteten, er biete der NSA eine Hintert\xfcr f\xfcr den Zugriff auf private Informationen. Die NSA hat diese Behauptungen jedoch zur\xfcckgewiesen und erkl\xe4rt, dass der Kurs rein p\xe4dagogischen Zwecken dient."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35481456",children:"Discussion Service"}),".\nDie NSA hat einen Cybersicherheitskurs entwickelt, aber es gibt Bedenken hinsichtlich der Verwendung von 0day-Exploits durch die Beh\xf6rde bei offensiven Operationen. Einige Benutzer stellen fest, dass die Trennung zwischen Angriff und Verteidigung weniger bedrohlich ist, als es scheint. Der Kurs ist Teil des CLARK-Systems, das teilweise von der NSA finanziert, aber haupts\xe4chlich von der Towson University betrieben wird. Einige Nutzer kritisieren, dass bestimmte Themen in dem Kurs nicht behandelt werden."]}),"\n",(0,t.jsx)(n.h2,{id:"schlechte-systeme-durch-schlechte-systeme-ersetzen",children:"Schlechte Systeme durch schlechte Systeme ersetzen"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://seths.blog/2023/04/replacing-bad-systems-with-bad-systems/",children:"Original"}),".\nIn seinem Blogbeitrag verwendet Seth die Metapher der veralteten Parkuhren, um die Notwendigkeit zu verdeutlichen, schlechte Systeme zu \xfcberdenken und zu verbessern. Deren Austausch mag zwar teuer erscheinen, aber zentralisierte Systeme wie die Parkmobile-App haben oft ihre eigenen M\xe4ngel. Um auf das urspr\xfcngliche Ziel zur\xfcckzukommen, Einnahmen zu generieren und das ganzt\xe4gige Parken zu verhindern, schl\xe4gt Seth vor, eine kostenlose App zu implementieren, die einen Code scannt, um eine bestimmte Parkzeit zu erm\xf6glichen. Andere einkommenssteigernde Optionen sind ein Online-Bezahldienst oder der Verkauf von Parkausweisen mit verschiedenen Rabattoptionen. W\xe4hrend es schwierig ist, UX-Entscheidungen f\xfcr ein \xf6ffentliches System zu treffen, haben sich verteilte Systeme wie WordPress aufgrund ihres dezentralen und benutzerfreundlichen Designs durchgesetzt. Der Hauptvorteil verteilter Systeme besteht darin, dass sie sich im Laufe der Zeit verbessern k\xf6nnen und nicht wie zentralisierte Systeme verkalken. Um weiter voranzukommen, schl\xe4gt Seth vor, dass wir besseren L\xf6sungen den Vorrang vor weiteren L\xf6sungen geben sollten."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35476350",children:"Discussion Service"}),".\nEin einfacheres Parksystem in D\xe4nemark hat manuelle Ziffernbl\xe4tter und Geldstrafen f\xfcr Betr\xfcger. Benutzer weisen auf \xe4hnliche Systeme in \xdcbersee hin. Komplexe L\xf6sungen werden oft trotz einfacher M\xf6glichkeiten eingesetzt. Parkuhren in Chicago brachten in 10 Jahren 200 Millionen Dollar ein. Neue elektronische Parkuhren sind weniger komfortabel als die klassischen. Die Beh\xf6rden tun sich schwer mit Zahlungssystemen und \xfcberlassen dies manchmal den Anbietern. Parkuhren werden vor allem wegen des Geldes eingesetzt, aber sie verhindern auch das ganzt\xe4gige Parken. Einem Kommentator zufolge hat der Artikel keinen Sinn, w\xe4hrend ein anderer den Autor kritisiert."]}),"\n",(0,t.jsx)(n.h2,{id:"neovim-09",children:"Neovim 0.9"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/neovim/neovim/commit/040f1459849ab05b04f6bb1e77b3def16b4c2f2b",children:"Original"}),'.\nNeovim Version 0.9.0 wurde ver\xf6ffentlicht, mit \xc4nderungen an iconv, libintl, optionalen Parametern, lua2dox, semantischen Token, \'+tui\', Unterst\xfctzung f\xfcr Yarn-Node-Module und Code-Block-Highlighting. Vim Version 8.2.2902 wurde auch mit Fehlerkorrekturen und verbesserter Lua-Scripting- und LSP-Unterst\xfctzung ver\xf6ffentlicht. Die neueste Version von Neovim bietet aufregende neue Funktionen und Stabilit\xe4tsverbesserungen, w\xe4hrend sich Vim auf Fehlerkorrekturen und verbesserte Funktionalit\xe4t konzentriert. Die Aktualisierungen von Neovim umfassen Verbesserungen an "treesitter", "tui" und "windows", von Software-Fixes bis hin zu verbesserter Dokumentation, die die Neovim-Erfahrung rationalisieren und seine Position als f\xe4hig und benutzerfreundlich festigen. Weitere Aktualisierungen umfassen \xc4nderungen an der Funktion \'expect_unchanged()\', EditorConfig und Syntaxhervorhebung f\xfcr Hilfedateien, eine Headless-Instanz, verbesserte LSP-Client-Funktionen und Plugin-Unterst\xfctzung f\xfcr GUIs.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35480629",children:"Discussion Service"}),".\nNeovim 0.9.0 hebt die Veraltung von 'exrc' auf und f\xfcgt eine \"Vertrauensdatenbank\" hinzu. Experten empfehlen appImage oder .local f\xfcr die Installation. EditorConfig-Unterst\xfctzung ist jetzt eingebaut. Debatte \xfcber die Vorz\xfcge von Neovim, w\xe4hrend einige die Fragmentierung kritisieren, schlagen andere Plugin-Manager vor. Neovim erm\xf6glicht neue Werkzeuge und Plugins. Lua hat Vorteile f\xfcr die Plugin-Entwicklung. Helix Editor hat ein Objekt-Verb-Modell, einen Null-Konfigurations-Sprachserver und einen Tutor. Seine Auswahl ist weniger flexibel, aber die Benutzer schw\xe4rmen von der Benutzerfreundlichkeit und Effizienz."]}),"\n",(0,t.jsx)(n.h2,{id:"fragen-sie-was-ist-ihre-beste-quelle-um-\xfcber-ki-entwicklungen-auf-dem-laufenden-zu-bleiben",children:"Fragen Sie Was ist Ihre beste Quelle, um \xfcber KI-Entwicklungen auf dem Laufenden zu bleiben?"}),"\n",(0,t.jsx)(n.p,{children:"N/A (Da dies nur eine allgemeine Anleitung zum Zusammenfassen ist, gibt es keinen Text zum Zusammenfassen)."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35479853",children:"Discussion Service"}),".\nDiscussion Service-Benutzer empfehlen Ressourcen, um sich \xfcber KI-Entwicklungen auf dem Laufenden zu halten, darunter die Papers with Code-Website, Blogs und Newsletters. Wegen der Informationsflut ist Vorsicht geboten. Einige bieten Ressourcen f\xfcr Anf\xe4nger. J\xfcngste Fortschritte in der KI, einschlie\xdflich Hardware- und Algorithmus-Innovationen, haben das Training gro\xdfer neuronaler Netze verbessert und eine Leistung auf menschlichem Niveau erreicht. Die Debatte \xfcber revolution\xe4re Durchbr\xfcche geht weiter."]}),"\n",(0,t.jsx)(n.h2,{id:"direkte-beweise-f\xfcr-den-gebrauch-mehrerer-drogen-in-der-bronzezeit-durch-einen-menschlichen-haartest",children:"Direkte Beweise f\xfcr den Gebrauch mehrerer Drogen in der Bronzezeit durch einen menschlichen Haartest"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://www.nature.com/articles/s41598-023-31064-2",children:"Original"}),".\nIn einer Studie wurden anhand der Analyse menschlicher Haare direkte Beweise f\xfcr den Konsum mehrerer psychoaktiver Pflanzenarten im bronzezeitlichen Menorca gefunden. Die Haare enthielten Ephedrin, Atropin und Scopolamin. Normalerweise schlie\xdfen Arch\xe4ologen von Artefakten auf den Konsum von bewusstseinsver\xe4ndernden Substanzen, doch diese Analyse ist direkt. Diese Entdeckung wirft ein neues Licht auf den Drogenkonsum in alten Gesellschaften und deutet auf spezielle Kenntnisse und einen m\xf6glichen schamanischen Gebrauch hin. Die Studie zeigt, wie wichtig es ist, die Rolle psychoaktiver Pflanzen und des Drogenkonsums vergangener Kulturen zu verstehen. Mehrere Studien weisen auf den Gebrauch psychoaktiver Pflanzen in alten Kulturen hin und unterstreichen die lange Geschichte des menschlichen Drogenkonsums."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35486923",children:"Discussion Service"}),".\nHaartests enth\xfcllen Drogen in der Bronzezeit mit mehreren psychoaktiven Arten. In den Kommentaren werden die gesellschaftlichen Auswirkungen des Drogenkonsums, pers\xf6nliche Entscheidungen, Bildung und Werte diskutiert. Drogenverbote haben ihre Wurzeln in der \xf6ffentlichen Gesundheit, der Moral und dem Rassismus. Der neutrale Artikel vermeidet politische Voreingenommenheit und Spekulationen."]}),"\n",(0,t.jsx)(n.h2,{id:"nypd-beamte-prahlen-in-einer-zuf\xe4lligen-aufnahme-mit-dem-abfeiern-von-\xfcberstunden",children:"NYPD-Beamte prahlen in einer zuf\xe4lligen Aufnahme mit dem Abfeiern von \xdcberstunden"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://gothamist.com/news/nypd-officers-brag-about-milking-overtime-call-detainees-names-in-accidental-recording",children:"Original"}),'.\nEine zuf\xe4llige Aufnahme, die bei der Verhaftung eines Bauarbeiters gemacht wurde, hat gezeigt, wie Polizeibeamte damit prahlen, "\xdcberstunden zu scheffeln" und abf\xe4llige Ausdr\xfccke gegen\xfcber Festgenommenen zu verwenden. Die Aufnahme wirft ein Licht darauf, wie sich die j\xfcngsten Reformen der Strafjustiz auf die Art und Weise ausgewirkt haben, wie Beamte Verhaftungen bearbeiten und \xdcberstunden sammeln. Es wird vermutet, dass Polizeibeamte die \xc4nderungen der Kautions- und Entdeckungsgesetze ausnutzen, um zus\xe4tzliche \xdcberstunden anzuh\xe4ufen. Die NYPD hat es abgelehnt, sich zu der Aufnahme zu \xe4u\xdfern, die auch unsensible \xc4u\xdferungen von Beamten \xfcber Inhaftierte enth\xe4lt.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35487036",children:"Discussion Service"}),".\nDie NYPD-Beamten prahlen damit, dass sie \xdcberstunden anh\xe4ufen, aber der Artikel enth\xfcllt, dass sie Schimpfw\xf6rter verwenden, Witze \xfcber die Einweisung von Menschen machen usw. Einige sind der Meinung, dass die Strafverfolgungsbeh\xf6rden in den USA viel schlimmere Probleme haben und die \xdcberstunden der Polizei ein Ablenkungsman\xf6ver sind. Andere sind der Meinung, dass das Abfeiern von \xdcberstunden durch Verl\xe4ngerung der Haftzeit verfassungswidrig ist und eine Anklage wegen eines Verbrechens verdient. Die Korruption in der Polizei hat zu Forderungen nach ihrer Abschaffung und Ersetzung gef\xfchrt. Das Fehlen einer angemessenen Aufsicht und Kontrolle erm\xf6glicht es, \xdcberstunden zu scheffeln und Missst\xe4nde zu beheben. Es gibt Bedenken hinsichtlich des Verhaltens von Personen, die Waffen erhalten und nach dem Gesetz bevorzugt behandelt werden."]}),"\n",(0,t.jsx)(n.h2,{id:"discussion-service-anzeigen-chatgdb---gpt-gesteuerter-gdb-assistent",children:"Discussion Service anzeigen: ChatGDB - GPT-gesteuerter GDB-Assistent"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"https://github.com/pgosar/ChatGDB",children:"Original"}),".\nChatGDB ist ein Werkzeug, das die Debugging-Erfahrung in GDB verbessert, indem es die Leistungsf\xe4higkeit von ChatGPT nutzt und die automatische Ausf\xfchrung von Befehlen in nat\xfcrlicher Sprache erm\xf6glicht. Benutzer k\xf6nnen ChatGPT auch bitten, den soeben ausgef\xfchrten Befehl zu erkl\xe4ren oder ihm sogar eine Frage zu stellen. Zur Installation m\xfcssen Python Version 3.3 oder h\xf6her und pip installiert sein, gefolgt von dem Befehl ",(0,t.jsx)(n.code,{children:"pip3 install chatgdb"})," und dem Erstellen einer ausf\xfchrbaren Datei mit ",(0,t.jsx)(n.code,{children:"chatgdb -k <API KEY>"}),". Das Tool kann innerhalb von GDB verwendet werden, indem man ",(0,t.jsx)(n.code,{children:"chat"})," gefolgt von dem gew\xfcnschten Befehl eingibt, und der Befehl ",(0,t.jsx)(n.code,{children:"explain"})," kann verwendet werden, um eine Erkl\xe4rung des vorherigen Befehls anzufordern oder eine Frage zu stellen."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35483933",children:"Discussion Service"}),'.\nChatGDB ist ein GPT-gest\xfctzter GDB-Assistent, der die Arbeitsabl\xe4ufe beim Debuggen verbessert. Der Discussion Service-Benutzer bemerkt den minimalen Code des Programms. ChatGPT beschleunigt das Verst\xe4ndnis des Benutzers f\xfcr ungewohnte Technik, Refactoring-Aufgaben. CLI-Version von ChatGPT vorgeschlagen. ChatGPT beschleunigt die Arbeitsabl\xe4ufe, obwohl einige Benutzer das Muskelged\xe4chtnis bevorzugen. ChatGPT-3 bietet eine nat\xfcrlichsprachliche Eingabeaufforderung f\xfcr GDB, die bei "Speicherlecks und Segmentierungsfehlern" hilfreich ist. Die Schnittstelle ist in bestimmten Szenarien immer noch unhandlich, w\xe4hrend Schriftart und Farbschema gut angenommen werden.']})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(l,{...e})}):l(e)}}}]);